"""Turn reserved binds into ready-to-run hotkey scripts."""

from __future__ import annotations

from .keymaps import ahk_hotkey, xbindkeys_keys
from .keys import Combo

FORMATS = ("ahk", "xbindkeys")


def _ahk_string(text: str) -> str:
    return '"' + text.replace("`", "``").replace('"', '`"') + '"'


def to_ahk(binds: list) -> str:
    lines = [
        "; Generated by BindsMaker - edit the actions, then double-click this file to run it.",
        "#Requires AutoHotkey v2.0",
        "#SingleInstance Force",
        "",
    ]
    for bind in binds:
        combo = Combo.parse(bind["combo"])
        label = bind.get("label") or str(combo)
        command = bind.get("command")
        lines.append(f"; {str(combo)} - {label}")
        lines.append(f"{ahk_hotkey(combo)}::")
        lines.append("{")
        if command:
            lines.append(f"    Run({_ahk_string(command)})")
        else:
            lines.append(f"    MsgBox({_ahk_string(f'{combo} pressed: put the action for “{label}” here')})")
        lines.append("}")
        lines.append("")
    return "\n".join(lines)


def to_xbindkeys(binds: list) -> str:
    lines = ["# Generated by BindsMaker - append to ~/.xbindkeysrc, then run: xbindkeys -p", ""]
    for bind in binds:
        combo = Combo.parse(bind["combo"])
        label = bind.get("label") or str(combo)
        command = bind.get("command") or f"notify-send 'BindsMaker' '{combo}: {label}'"
        lines.append(f"# {combo} - {label}")
        lines.append('"' + command.replace('"', '\\"') + '"')
        lines.append(f"    {xbindkeys_keys(combo)}")
        lines.append("")
    return "\n".join(lines)


def export(binds: list, fmt: str) -> str:
    if fmt == "ahk":
        return to_ahk(binds)
    if fmt == "xbindkeys":
        return to_xbindkeys(binds)
    raise ValueError(f"unknown format {fmt!r}; choose from {', '.join(FORMATS)}")
